// machines/plaits: VCF-VA's filter loop (engines/vcf.c, vcf_render), hand-written SISD kernel.
// Generated by lib/gen_vcf_kernel.py; do not edit by hand.
//
// vcf_filter_kernel(Vcf *s, const float *k, float *out, float *aux, int size): k[0..4] = the increments of
//   previous_cutoff_, previous_stage2_gain_, previous_q_, previous_gain_, previous_sub_gain_; out holds the main
//   oscillator, aux the sub oscillator; out and aux receive the filter's outputs; the filter state and the last
//   sample's g_, r_, h_ go back to s->svf_ (size >= 1; the C stores uninitialised locals for size 0, the engine always
//   renders 16). Bit-identical to selcc's code of the C loop (-DPL_VCF_C) (tests/plaits/test_vcf_kernel.py).
//
// State on return: R0-R8, R12, I4 and the flags change; every other register is as on entry (R9-R11, R13-R15 saved
// above I7; I0, I1, I2, M6, L0, L1, L2, L4 pushed through R0, M6 = 1 and L0 = L1 = L2 = L4 = 0 set here). No SIMD.
// ABI: as the other kernels (lib/wavetable_sm.s). Assembled under .COMPRESS; integer additions in their 48-bit form.

.SECTION/PM seg_pmco;
.GLOBAL vcf_filter_kernel.;
.COMPRESS;

vcf_filter_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L4 = 0;
    I7=MODIFY (I7,-20)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I2 = R4;                                            // s
    I4 = R8;                                            // k
    I0 = R12;                                           // out
    R0 = DM(1, I6);                                     // aux
    I1 = R0;
    R0 = DM(0, I4);
    DM(7, I7) = R0;
    R0 = DM(1, I4);
    DM(8, I7) = R0;
    R0 = DM(2, I4);
    DM(9, I7) = R0;
    R0 = DM(3, I4);
    DM(10, I7) = R0;
    R0 = DM(4, I4);
    DM(11, I7) = R0;
    R0 = DM(2, I6);                                     // size
    DM(12, I7) = R0;
    R15 = DM(6, I2);                                    // a1 = state_1_[0]
    R14 = DM(8, I2);                                    // a2 = state_2_[0]
    R13 = DM(7, I2);                                    // b1 = state_1_[1]
    R12 = DM(9, I2);                                    // b2 = state_2_[1]
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _vfk_end;
_vfk_loop:
    R0 = DM(24, I2);
    R1 = DM(7, I7);
    F0 = F0 + F1;                                       // c = minf(cutoff_modulation.Next(), 0.25f)
    DM(24, I2) = R0;
    R1 = 0x3E800000;                                    // q
    COMP(F0, F1);
    IF GE R0 = R1 OR R1;
    R9 = DM(26, I2);
    R1 = DM(9, I7);
    F9 = F9 + F1;                                       // qi = q_modulation.Next()
    DM(26, I2) = R9;
    R1 = DM(25, I2);
    R2 = DM(8, I7);
    F1 = F1 + F2;                                       // st2 = stage2_gain_modulation.Next()
    DM(25, I2) = R1;
    DM(19, I7) = R1;
    F1 = F0 * F0;                                       // g = tan_fast(c): f * (pi + f2 * (a + b * f2))
    R2 = 0x425F2649;                                    // b
    F2 = F2 * F1;
    R3 = 0x4121BA8F;                                    // a
    F2 = F3 + F2;
    F2 = F1 * F2;
    R3 = 0x40490FDB;                                    // pi
    F2 = F3 + F2;
    F10 = F0 * F2;
    DM(13, I7) = R10;
    R1 = 0x3F000000;                                    // half
    F1 = F1 + F9;                                       // r0 = 1.0f / (0.5f + qi)
    R2 = 0x3F800000;                                    // one
    R6 = 0x40000000;                                    // two
    F4 = RECIPS F1;
    F5 = F1 * F4;                                       // selcc division
    F5 = F6 - F5;
    F4 = F4 * F5;
    F5 = F1 * F4;
    F5 = F6 - F5;
    F4 = F4 * F5;
    F6 = F2 * F4;
    F5 = F1 * F6;
    F5 = F2 - F5;
    F5 = F5 * F4;
    F6 = F6 + F5;
    DM(14, I7) = R6;
    F1 = F6 * F10;                                      // h0 = 1.0f / (1.0f + r0 * g0 + g0 * g0)
    F1 = F2 + F1;
    F3 = F10 * F10;
    F1 = F1 + F3;
    R6 = 0x40000000;                                    // two
    F4 = RECIPS F1;
    F5 = F1 * F4;                                       // selcc division
    F5 = F6 - F5;
    F4 = F4 * F5;
    F5 = F1 * F4;
    F5 = F6 - F5;
    F4 = F4 * F5;
    F6 = F2 * F4;
    F5 = F1 * F6;
    F5 = F2 - F5;
    F5 = F5 * F4;
    F6 = F6 + F5;
    DM(15, I7) = R6;
    R1 = 0x3CCCCCCD;                                    // 0.025
    F1 = F1 * F9;                                       // r1 = 1.0f / (0.5f + 0.025f * qi)
    R3 = 0x3F000000;                                    // half
    F1 = F3 + F1;
    R6 = 0x40000000;                                    // two
    F4 = RECIPS F1;
    F5 = F1 * F4;                                       // selcc division
    F5 = F6 - F5;
    F4 = F4 * F5;
    F5 = F1 * F4;
    F5 = F6 - F5;
    F4 = F4 * F5;
    F6 = F2 * F4;
    F5 = F1 * F6;
    F5 = F2 - F5;
    F5 = F5 * F4;
    F6 = F6 + F5;
    DM(16, I7) = R6;
    F1 = F6 * F10;                                      // h1 = 1.0f / (1.0f + r1 * g1 + g1 * g1)
    F1 = F2 + F1;
    F3 = F10 * F10;
    F1 = F1 + F3;
    R6 = 0x40000000;                                    // two
    F4 = RECIPS F1;
    F5 = F1 * F4;                                       // selcc division
    F5 = F6 - F5;
    F4 = F4 * F5;
    F5 = F1 * F4;
    F5 = F6 - F5;
    F4 = F4 * F5;
    F6 = F2 * F4;
    F5 = F1 * F6;
    F5 = F2 - F5;
    F5 = F5 * F4;
    F6 = F6 + F5;
    DM(17, I7) = R6;
    R11 = DM(27, I2);
    R1 = DM(10, I7);
    F11 = F11 + F1;                                     // gi = gain_modulation.Next()
    DM(27, I2) = R11;
    DM(18, I7) = R11;
    R1 = DM(28, I2);
    R2 = DM(11, I7);
    F1 = F1 + F2;                                       // sub_gain_modulation.Next()
    DM(28, I2) = R1;
    R0 = DM(I1, M5);                                    // input = SoftClip((out[i] + aux[i] * sub_gain) * gi)
    F0 = F0 * F1;
    R1 = DM(I0, M5);
    F9 = F1 + F0;
    F9 = F9 * F11;
    F1 = F9 * F9;                                       // SoftLimit: x * (27.0f + x * x) / (27.0f + 9.0f * x * x)
    R2 = 0x41D80000;                                    // 27
    F1 = F2 + F1;
    F1 = F9 * F1;
    R3 = 0x41100000;                                    // 9
    F3 = F3 * F9;
    F3 = F3 * F9;
    F3 = F2 + F3;
    R6 = 0x40000000;                                    // two
    F4 = RECIPS F3;
    F5 = F3 * F4;                                       // selcc division
    F5 = F6 - F5;
    F4 = F4 * F5;
    F5 = F3 * F4;
    F5 = F6 - F5;
    F4 = F4 * F5;
    F6 = F1 * F4;
    F5 = F3 * F6;
    F5 = F1 - F5;
    F5 = F5 * F4;
    F6 = F6 + F5;
    R2 = 0x40400000;                                    // 3
    COMP(F9, F2);                                       // x > 3.0f (a NaN too, as selcc compares): 1.0f
    R2 = 0x3F800000;                                    // one
    IF GT R6 = R2 OR R2;
    R2 = 0xC0400000;                                    // -3
    COMP(F9, F2);                                       // x < -3.0f: -1.0f
    R2 = 0xBF800000;                                    // -1
    IF LT R6 = R2 OR R2;
    R9 = PASS R6;
    R4 = DM(13, I7);
    R5 = DM(14, I7);
    R6 = DM(15, I7);
    F7 = F5 * F15;                                      // hp = (in - r s1 - g s1 - s2) * h
    F7 = F9 - F7;
    F8 = F4 * F15;
    F7 = F7 - F8;
    F7 = F7 - F14;
    F7 = F7 * F6;
    F8 = F4 * F7;                                       // bp = g hp + s1
    F8 = F8 + F15;
    F15 = F4 * F7;                                      // s1 = g hp + bp
    F15 = F15 + F8;
    F0 = F4 * F8;                                       // lp = g bp + s2
    F0 = F0 + F14;
    F14 = F4 * F8;                                      // s2 = g bp + lp
    F14 = F14 + F0;
    DM(20, I7) = R7;
    R11 = DM(18, I7);
    F9 = F0 * F11;                                      // lp = SoftClip(lp * gi)
    F1 = F9 * F9;                                       // SoftLimit: x * (27.0f + x * x) / (27.0f + 9.0f * x * x)
    R2 = 0x41D80000;                                    // 27
    F1 = F2 + F1;
    F1 = F9 * F1;
    R3 = 0x41100000;                                    // 9
    F3 = F3 * F9;
    F3 = F3 * F9;
    F3 = F2 + F3;
    R6 = 0x40000000;                                    // two
    F4 = RECIPS F3;
    F5 = F3 * F4;                                       // selcc division
    F5 = F6 - F5;
    F4 = F4 * F5;
    F5 = F3 * F4;
    F5 = F6 - F5;
    F4 = F4 * F5;
    F6 = F1 * F4;
    F5 = F3 * F6;
    F5 = F1 - F5;
    F5 = F5 * F4;
    F6 = F6 + F5;
    R2 = 0x40400000;                                    // 3
    COMP(F9, F2);                                       // x > 3.0f (a NaN too, as selcc compares): 1.0f
    R2 = 0x3F800000;                                    // one
    IF GT R6 = R2 OR R2;
    R2 = 0xC0400000;                                    // -3
    COMP(F9, F2);                                       // x < -3.0f: -1.0f
    R2 = 0xBF800000;                                    // -1
    IF LT R6 = R2 OR R2;
    R9 = PASS R6;
    R4 = DM(13, I7);
    R5 = DM(16, I7);
    R6 = DM(17, I7);
    F7 = F5 * F13;                                      // hp = (in - r s1 - g s1 - s2) * h
    F7 = F9 - F7;
    F8 = F4 * F13;
    F7 = F7 - F8;
    F7 = F7 - F12;
    F7 = F7 * F6;
    F8 = F4 * F7;                                       // bp = g hp + s1
    F8 = F8 + F13;
    F13 = F4 * F7;                                      // s1 = g hp + bp
    F13 = F13 + F8;
    F0 = F4 * F8;                                       // lp = g bp + s2
    F0 = F0 + F12;
    F12 = F4 * F8;                                      // s2 = g bp + lp
    F12 = F12 + F0;
    F1 = F0 * F0;                                       // SoftLimit: x * (27.0f + x * x) / (27.0f + 9.0f * x * x)
    R2 = 0x41D80000;                                    // 27
    F1 = F2 + F1;
    F1 = F0 * F1;
    R3 = 0x41100000;                                    // 9
    F3 = F3 * F0;
    F3 = F3 * F0;
    F3 = F2 + F3;
    R6 = 0x40000000;                                    // two
    F4 = RECIPS F3;
    F5 = F3 * F4;                                       // selcc division
    F5 = F6 - F5;
    F4 = F4 * F5;
    F5 = F3 * F4;
    F5 = F6 - F5;
    F4 = F4 * F5;
    F6 = F1 * F4;
    F5 = F3 * F6;
    F5 = F1 - F5;
    F5 = F5 * F4;
    F6 = F6 + F5;
    R2 = 0x40400000;                                    // 3
    COMP(F0, F2);                                       // x > 3.0f (a NaN too, as selcc compares): 1.0f
    R2 = 0x3F800000;                                    // one
    IF GT R6 = R2 OR R2;
    R2 = 0xC0400000;                                    // -3
    COMP(F0, F2);                                       // x < -3.0f: -1.0f
    R2 = 0xBF800000;                                    // -1
    IF LT R6 = R2 OR R2;
    R0 = PASS R6;
    F0 = F0 - F9;                                       // lp += st2 * (SoftClip(lp2) - lp)
    R1 = DM(19, I7);
    F0 = F1 * F0;
    F9 = F9 + F0;
    DM(I0, M6) = R9;                                    // out[i] = lp
    R9 = DM(20, I7);
    R11 = DM(18, I7);
    F9 = F9 * F11;                                      // aux[i] = SoftClip(hp * gi)
    F1 = F9 * F9;                                       // SoftLimit: x * (27.0f + x * x) / (27.0f + 9.0f * x * x)
    R2 = 0x41D80000;                                    // 27
    F1 = F2 + F1;
    F1 = F9 * F1;
    R3 = 0x41100000;                                    // 9
    F3 = F3 * F9;
    F3 = F3 * F9;
    F3 = F2 + F3;
    R6 = 0x40000000;                                    // two
    F4 = RECIPS F3;
    F5 = F3 * F4;                                       // selcc division
    F5 = F6 - F5;
    F4 = F4 * F5;
    F5 = F3 * F4;
    F5 = F6 - F5;
    F4 = F4 * F5;
    F6 = F1 * F4;
    F5 = F3 * F6;
    F5 = F1 - F5;
    F5 = F5 * F4;
    F6 = F6 + F5;
    R2 = 0x40400000;                                    // 3
    COMP(F9, F2);                                       // x > 3.0f (a NaN too, as selcc compares): 1.0f
    R2 = 0x3F800000;                                    // one
    IF GT R6 = R2 OR R2;
    R2 = 0xC0400000;                                    // -3
    COMP(F9, F2);                                       // x < -3.0f: -1.0f
    R2 = 0xBF800000;                                    // -1
    IF LT R6 = R2 OR R2;
    R9 = PASS R6;
    DM(I1, M6) = R9;
    R0 = DM(12, I7);
    R1 = 1;
    .NOCOMPRESS;
    R0 = R0 - R1;
    .COMPRESS;
    DM(12, I7) = R0;
    IF NE JUMP _vfk_loop;
    R0 = DM(13, I7);
    DM(0, I2) = R0;                                     // g_[0], g_[1]
    DM(1, I2) = R0;
    R0 = DM(14, I7);
    DM(2, I2) = R0;                                     // r_[0]
    R0 = DM(16, I7);
    DM(3, I2) = R0;                                     // r_[1]
    R0 = DM(15, I7);
    DM(4, I2) = R0;                                     // h_[0]
    R0 = DM(17, I7);
    DM(5, I2) = R0;                                     // h_[1]
    DM(6, I2) = R15;
    DM(8, I2) = R14;
    DM(7, I2) = R13;
    DM(9, I2) = R12;
_vfk_end:
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,20)(NW);
    L4 = DM(1, I7);
    L2 = DM(2, I7);
    L1 = DM(3, I7);
    L0 = DM(4, I7);
    M6 = DM(5, I7);
    I2 = DM(6, I7);
    I1 = DM(7, I7);
    I0 = DM(8, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
